<?php $pageTitle = 'Sales reports'; ?>
<section class="page-intro"><div class="intro-inner"><span class="eyebrow">Management reporting</span><h1>Sales and transactions</h1><p>Figures are calculated from stored reservations and recorded manual payments. Pending/cancelled bookings are excluded from booked sales.</p></div></section><section class="content-section"><div class="metrics-grid"><article class="metric"><span>Reservations</span><strong><?= (int) $summary['orders_count'] ?></strong></article><article class="metric"><span>Booked total</span><strong><?= rc_money(rc_cents($summary['booked_total'])) ?></strong></article><article class="metric"><span>Payments recorded</span><strong><?= rc_money(rc_cents($summary['paid_total'])) ?></strong></article><article class="metric"><span>Outstanding balance</span><strong><?= rc_money(rc_cents($summary['balance_total'])) ?></strong></article></div><section class="surface"><div class="surface-heading"><h2>Payment transactions</h2><span>Most recent 100 grouped records</span></div><?php if ($payments): ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Method</th><th>Transactions</th><th>Amount</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= rc_e($payment['payment_day']) ?></td><td><?= rc_e($payment['payment_method']) ?></td><td><?= (int) $payment['transactions'] ?></td><td><?= rc_money(rc_cents($payment['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><strong>No payments recorded yet</strong>Manual payment entries will appear in this report.</div><?php endif; ?></section><p class="report-note">This page reports stored reservation and payment data. It is not a tax/accounting system.</p></section>
